export const OPEN_NEXT_CLI_STAND_IN = [
  "import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';",
  "import { createServer, request } from 'node:http';",
  '',
  'const here = (file) => new URL(file, import.meta.url);',
  "const plan = JSON.parse(readFileSync(here('plan.json'), 'utf8'));",
  'const [command, ...rest] = process.argv.slice(2);',
  "appendFileSync(here('calls.jsonl'), `${JSON.stringify([command, ...rest])}\\n`);",
  '',
  "if (command === 'build' && plan.build === 'fails') {",
  "  process.stderr.write('Error: Next.js build failed\\n');",
  '  process.exitCode = 1;',
  "} else if (command === 'build' && plan.build === 'leaves the worker') {",
  "  mkdirSync('.open-next/assets', { recursive: true });",
  "  writeFileSync('.open-next/worker.js', 'export default {};\\n');",
  "} else if (command === 'preview' && !existsSync('.open-next/worker.js')) {",
  "  process.stderr.write('ERROR Could not find compiled Open Next config, did you run the build command?\\n');",
  '  process.exitCode = 1;',
  "} else if (command === 'preview') {",
  "  const port = Number(rest[rest.indexOf('--port') + 1]);",
  '  const server = createServer((incoming, outgoing) => {',
  '    const forwarded = request(`${plan.worker}${incoming.url}`, { method: incoming.method, headers: incoming.headers }, (answer) => {',
  "      for (const line of JSON.parse(answer.headers['x-worker-log'] ?? '[]')) process.stdout.write(`${line}\\n`);",
  '      outgoing.writeHead(answer.statusCode, answer.headers);',
  '      answer.pipe(outgoing);',
  '    });',
  '    incoming.pipe(forwarded);',
  '  });',
  '  setTimeout(() => server.listen(port, () => process.stdout.write(`Ready on http://localhost:${port}\\n`)), 1500);',
  '}',
  '',
].join('\n');
